      var fu = -diff;
      if (fu < 60000) return 'in ' + Math.round(fu / 1000) + 's';
      if (fu < 3600000) return 'in ' + Math.floor(fu / 60000) + 'm';
      if (fu < 86400000) return 'in ' + Math.floor(fu / 3600000) + 'h';
